$vels=diffrrands(250,330,30,2) // speed of airplane in m/s, not to exceed 340 m/s
$c=340 // speed of sound in m/s
// build three different types of distractors
// $c + $vels (the first one will be correct)
for ($i=0..1) {$questions[]=prettyreal($c+$vels[$i])." m/s relative to the ground"}
// $c - $vels (all incorrect)
for ($i=0..1) {$questions[]=prettyreal($c-$vels[$i])." m/s relative to the ground"}
// $c (incorrect here)
$questions[]=prettyreal($c)." m/s relative to the ground"
$answer=0 // correct by construction and question wording

